// Exact GRX classification of all-odd k-block representations at length N over D_(2p) (rotation slice, 2026-10-18).
// C++ port of kblock_exact_v3.py (same mathematics; written independently of the Python loops):
//  * F = sum l_i ranges over k, k+2, ... with H = (F-k)/2 <= p-1 (pairs bound), R = N-F, and the proved prefilters
//    R <= 3p-2 (EGZ) and, if F >= 2 and N <= 4p-1, R + H <= 3p-2 (Davenport-alpha);
//  * rotation multisets Y (multiplicities over Z_p) are generated by a pruned DFS using only the GRX zero pattern
//    (no zero-sum of even length in [2p-2H, 2p]);
//  * distributions of Y into k ordered runs, enumerated up to cyclic rotation of the run index (theta ranges over all
//    of Z_p^k with sum 0, so a cyclic rotation of (runs, theta) is again a datum; GRX is invariant);
//  * every pattern z in {+} x {+-}^(k-1): admissible even m = 2p - C, C even in [Phi, F - (k - Phi)], m in [0, R];
//    W_z = union of the size-m signed subset-sum sets; theta avoids iff T(z) = sum_{z_i=+} theta_i notin W_z for all z.
// Output: one line per NON-RIGID avoiding datum (F, runs, theta) for independent raw-DP re-verification in Python
// (code/verify_kblock_hits_v1.py), and a SUMMARY line.  Usage: kblock_exact p N k nonrigid_only(0/1) max_print
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>
using namespace std;
typedef uint32_t M;
static int P, NN, K, NONRIG, MAXPRINT;
static M FULL;
static inline M rotm(M m, int s) { s %= P; if (s < 0) s += P; if (!s) return m; return ((m << s) | (m >> (P - s))) & FULL; }
static inline M negm(M m) { M o = m & 1u; for (int v = 1; v < P; v++) if ((m >> v) & 1u) o |= 1u << (P - v); return o; }

static long long cntY = 0, cntDist = 0, cntData = 0, avRig = 0, avNon = 0, printed = 0;

// profile of a multiplicity vector: prof[m] = sums of size-m sub-multisets
static void profile(const vector<int>& cnt, int maxm, vector<M>& prof) {
    prof.assign(maxm + 1, 0); prof[0] = 1;
    for (int v = 0; v < P; v++) {
        int c = cnt[v]; if (!c) continue;
        vector<M> nw = prof;
        for (int L = 0; L <= maxm; L++) {
            M m = prof[L]; if (!m) continue;
            M acc = m;
            for (int j = 1; j <= c && L + j <= maxm; j++) { acc = rotm(acc, v); nw[L + j] |= acc; }
        }
        prof.swap(nw);
    }
}

static bool isRigid(const vector<int>& cnt) {
    if (cnt[0]) return false;
    int x = -1;
    for (int v = 1; v < P; v++) if (cnt[v]) {
        if (x < 0) x = v; else if (v != x && v != P - x) return false;
    }
    return true;
}

// ---- Y generation ----
static vector<vector<int>> Ys;
static int gR, gLo;
static bool badProf(const vector<M>& pr) {
    int maxL = (int)pr.size() - 1;
    for (int L = max(gLo, 2); L <= maxL; L++) if (!(L & 1) && (pr[L] & 1u)) return true;
    return false;
}
static void ydfs(int v, int left, vector<int>& cnt, const vector<M>& prof) {
    int maxL = (int)prof.size() - 1;
    if (v == P - 1) {
        vector<M> pr = prof;
        int c = left;
        if (c) {
            vector<M> nw = pr;
            for (int L = 0; L <= maxL; L++) { M m = pr[L]; if (!m) continue; M acc = m;
                for (int j = 1; j <= c && L + j <= maxL; j++) { acc = rotm(acc, v); nw[L + j] |= acc; } }
            pr.swap(nw);
        }
        if (!badProf(pr)) { cnt[v] = c; Ys.push_back(cnt); cnt[v] = 0; }
        return;
    }
    vector<M> pr = prof;
    for (int c = 0; c <= left; c++) {
        if (c) {
            vector<M> nw = pr;
            for (int L = 0; L <= maxL; L++) { M m = pr[L]; if (!m) continue; nw[L] |= 0; }
            // add exactly one more copy of v to the multiset represented by pr
            vector<M> nx = pr;
            for (int L = 0; L < maxL; L++) { M m = pr[L]; if (!m) continue; nx[L + 1] |= rotm(m, v); }
            pr.swap(nx);
            if (badProf(pr)) break;
        }
        cnt[v] = c;
        ydfs(v + 1, left - c, cnt, pr);
        cnt[v] = 0;
    }
}

// ---- distributions ----
static int gF;
static vector<vector<int>> runs;  // runs[i][v]
static vector<int> theta;
static vector<int> pats;           // bitmask of plus-set (bit 0 = run 0 always set)
static vector<M> Wz;

static void evalDistribution(bool rigidY) {
    cntDist++;
    int R = gR;
    vector<vector<M>> prof(K), nprof(K);
    for (int i = 0; i < K; i++) {
        int ri = 0; for (int v = 0; v < P; v++) ri += runs[i][v];
        profile(runs[i], ri, prof[i]);
        nprof[i].resize(prof[i].size());
        for (size_t m = 0; m < prof[i].size(); m++) nprof[i][m] = negm(prof[i][m]);
    }
    int np = (int)pats.size();
    Wz.assign(np, 0);
    vector<M> comb, nw;
    for (int t = 0; t < np; t++) {
        int z = pats[t];
        comb.assign(R + 1, 0); comb[0] = 1;
        int cur = 0;
        for (int i = 0; i < K; i++) {
            const vector<M>& pr = ((z >> i) & 1) ? prof[i] : nprof[i];
            int ri = (int)pr.size() - 1;
            nw.assign(R + 1, 0);
            for (int a = 0; a <= cur; a++) {
                M ma = comb[a]; if (!ma) continue;
                for (int b = 0; b <= ri && a + b <= R; b++) {
                    M mb = pr[b]; if (!mb) continue;
                    M acc = 0;
                    for (int s = 0; s < P; s++) if ((ma >> s) & 1u) acc |= rotm(mb, s);
                    nw[a + b] |= acc;
                }
            }
            comb.swap(nw); cur += ri;
        }
        int Phi = 0;
        for (int i = 0; i < K; i++) { int zi = (z >> i) & 1, zj = (z >> ((i + 1) % K)) & 1; if (zi != zj) Phi++; }
        int Cmax = gF - (K - Phi);
        M w = 0;
        for (int C = Phi; C <= Cmax; C += 2) { int m = 2 * P - C; if (m >= 0 && m <= R) w |= comb[m]; }
        Wz[t] = w;
    }
    // theta DFS with pruning: pattern t is decidable once all its plus-indices or all its minus-indices are assigned
    theta.assign(K, 0);
    // order of checks: for depth d (theta_0..theta_{d-1} assigned) a pattern with plus-set within [0,d) or minus-set within [0,d)
    vector<vector<int>> checkAt(K + 1);
    for (int t = 0; t < np; t++) {
        int z = pats[t];
        int maxPlus = -1, maxMinus = -1;
        for (int i = 0; i < K; i++) { if ((z >> i) & 1) maxPlus = i; else maxMinus = i; }
        int d1 = maxPlus + 1, d2 = (maxMinus < 0) ? K + 1 : maxMinus + 1;
        int d = min(d1, d2);
        if (d > K - 1) d = K;  // decided only when all assigned
        checkAt[d].push_back(t);
    }
    // iterative DFS over theta_0..theta_{K-2}; theta_{K-1} = -sum
    vector<int> th(K, 0);
    function_dfs:;
    struct Frame { int d; };
    // recursive lambda substitute
    std::vector<int> stackv(K, -1);
    int d = 0;
    // simple recursion via explicit loop
    std::function<void(int, int)> rec;
    rec = [&](int depth, int partial) {
        if (depth == K - 1) {
            th[K - 1] = ((-partial) % P + P) % P;
            for (int t : checkAt[K]) { int z = pats[t]; int T = 0; for (int i = 0; i < K; i++) if ((z >> i) & 1) T += th[i]; T %= P; if ((Wz[t] >> T) & 1u) return; }
            for (int t : checkAt[K - 1]) { int z = pats[t]; int T = 0; for (int i = 0; i < K; i++) if ((z >> i) & 1) T += th[i]; T %= P; if ((Wz[t] >> T) & 1u) return; }
            cntData++;
            if (rigidY) avRig++; else {
                avNon++;
                if (printed < MAXPRINT) {
                    printed++;
                    printf("HIT F=%d runs=", gF);
                    for (int i = 0; i < K; i++) { printf(i ? "|" : ""); for (int v = 0; v < P; v++) printf(v ? ",%d" : "%d", runs[i][v]); }
                    printf(" theta=");
                    for (int i = 0; i < K; i++) printf(i ? ",%d" : "%d", th[i]);
                    printf("\n");
                }
            }
            return;
        }
        for (int x = 0; x < P; x++) {
            th[depth] = x;
            bool ok = true;
            for (int t : checkAt[depth + 1]) {
                int z = pats[t]; int T = 0; bool plusKnown = true;
                // decide by whichever side is fully assigned
                int maxPlus = -1; for (int i = 0; i < K; i++) if ((z >> i) & 1) maxPlus = i;
                if (maxPlus <= depth) { for (int i = 0; i <= depth; i++) if ((z >> i) & 1) T += th[i]; }
                else { plusKnown = false; int S = 0; for (int i = 0; i <= depth; i++) if (!((z >> i) & 1)) S += th[i]; T = -S; }
                (void)plusKnown;
                T %= P; if (T < 0) T += P;
                if ((Wz[t] >> T) & 1u) { ok = false; break; }
            }
            if (ok) rec(depth + 1, (partial + x) % P);
        }
    };
    (void)stackv; (void)d;
    rec(0, 0);
}

static void distRec(int v, const vector<int>& cnt, bool rigidY);
static vector<int> curCnt;
static void compRec(int v, int i, int left, const vector<int>& cnt, bool rigidY) {
    if (i == K - 1) { runs[i][v] = left; distRec(v + 1, cnt, rigidY); runs[i][v] = 0; return; }
    for (int a = 0; a <= left; a++) { runs[i][v] = a; compRec(v, i + 1, left - a, cnt, rigidY); }
    runs[i][v] = 0;
}
static bool minimalRotation() {
    // run vector (as sequences of multiplicity vectors) must be lexicographically minimal among its cyclic rotations
    for (int s = 1; s < K; s++) {
        for (int i = 0; i < K; i++) {
            const vector<int>& a = runs[i]; const vector<int>& b = runs[(i + s) % K];
            if (a == b) continue;
            if (b < a) return false; else goto next;
        }
        next:;
    }
    return true;
}
static void distRec(int v, const vector<int>& cnt, bool rigidY) {
    if (v == P) { if (minimalRotation()) evalDistribution(rigidY); return; }
    if (!cnt[v]) { distRec(v + 1, cnt, rigidY); return; }
    compRec(v, 0, cnt[v], cnt, rigidY);
}

int main(int argc, char** argv) {
    if (argc < 6) { fprintf(stderr, "usage\n"); return 2; }
    P = atoi(argv[1]); NN = atoi(argv[2]); K = atoi(argv[3]); NONRIG = atoi(argv[4]); MAXPRINT = atoi(argv[5]);
    FULL = (P == 32) ? 0xffffffffu : ((1u << P) - 1);
    for (int z = 0; z < (1 << K); z++) if (z & 1) pats.push_back(z);
    runs.assign(K, vector<int>(P, 0));
    for (int F = K; F <= NN; F += 2) {
        int R = NN - F, H = (F - K) / 2;
        if (H > P - 1) break;
        if (R > 3 * P - 2) continue;
        if (F >= 2 && NN <= 4 * P - 1 && R + H > 3 * P - 2) continue;
        gF = F; gR = R; gLo = 2 * P - 2 * H;
        Ys.clear();
        vector<int> cnt(P, 0);
        int maxL = min(2 * P, R);
        vector<M> prof(maxL + 1, 0); prof[0] = 1;
        ydfs(0, R, cnt, prof);
        for (auto& y : Ys) {
            bool rg = isRigid(y);
            if (NONRIG && rg) continue;
            cntY++;
            distRec(0, y, rg);
        }
    }
    printf("SUMMARY p=%d N=%d k=%d nonrigid_only=%d Y=%lld distributions=%lld avoid_rigid=%lld avoid_nonrigid=%lld\n",
           P, NN, K, NONRIG, cntY, cntDist, avRig, avNon);
    return 0;
}
